tvdGeom(){const C=500,R0=120,N=11;const pts=[];for(let n=1;n<=88;n++){const r=Math.ceil(n/N);const k=n-(r-1)*N;const a=(-90+k*360/N)*Math.PI/180;const R=R0+(r-1)*80;pts.push({n,x:C+R*Math.cos(a),y:C+R*Math.sin(a),ring:r,chk:n%10===0})}return pts},
