(function(){
'use strict';
if(typeof window === 'undefined' || !window.G) return;
const G = window.G;
function initTroopsState(){
  if(!G.S) return;
  const s = G.S;
  if(!s.troops){
    s.troops = {
      ranged: 50,  // Стрелки
      melee: 80,   // Штурмовики
      cavalry: 30  // Рейдеры
    };
  }
  if(!s.training){
    s.training = null; // {type:'ranged', amt:20, end: Date.now()+60000, totalSec:60}
  }
  if(!s.armyFormation){
    s.armyFormation = 'balanced'; // 'balanced' | 'assault' | 'defensive' | 'flank'
  }
  if(!s.hospital){
    s.hospital = {
      wounded: { ranged: 5, melee: 10, cavalry: 2 },
      healing: null
    };
  }
}
const TROOP_TYPES = {
  melee: {
    n: 'Штурмовики',
    i: '🛡️',
    role: 'Тяжёлая пехота · Авангард',
    counter: 'ranged',
    counterText: '🛡️ > 🎯 Преимущество над Стрелками (+30% урона, -25% входящего)',
    desc: 'Тяжело экипированные штурмовики с ростовыми щитами. Удерживают рубежи и снижают урон по воротам.',
    atk: 8,
    def: 18,
    spd: 0.9,
    cost: { food: 20, wood: 10, time: 8 },
    synergyHero: 'Джо / Влад'
  },
  ranged: {
    n: 'Стрелки',
    i: '🎯',
    role: 'Снайперы · Огневая мощь',
    counter: 'cavalry',
    counterText: '🎯 > 🏍️ Преимущество над Рейдерами (+30% урона, бронебойный залп)',
    desc: 'Меткие стрелки с карабинами и винтовками. Наносят сокрушительный прицельный урон из-за укрытий.',
    atk: 18,
    def: 6,
    spd: 1.0,
    cost: { food: 15, metal: 12, time: 10 },
    synergyHero: 'Елена / Мира'
  },
  cavalry: {
    n: 'Рейдеры',
    i: '🏍️',
    role: 'Мото-отряды · Фланговый прорыв',
    counter: 'melee',
    counterText: '🏍️ > 🛡️ Преимущество над Штурмовиками (+30% урона, обход с фланга)',
    desc: 'Быстроходные разведчики на багги и байках. Обеспечивают мобильность на ТВД и внезапные налёты.',
    atk: 14,
    def: 10,
    spd: 1.6,
    cost: { food: 25, metal: 15, time: 12 },
    synergyHero: 'Кай / Следопыты'
  }
};
const ARMY_FORMATIONS = {
  balanced: {
    id: 'balanced',
    n: 'Сбалансированная',
    i: '⚖️',
    desc: '+10% к Атаке, Защите и Здоровью всех отрядов',
    bonus: { atk: 1.10, def: 1.10, spd: 1.05 }
  },
  assault: {
    id: 'assault',
    n: 'Штурмовой Клин',
    i: '⚔️',
    desc: '+25% к урону Стрелков и Рейдеров, -10% защиты',
    bonus: { atk: 1.25, def: 0.90, spd: 1.15 }
  },
  defensive: {
    id: 'defensive',
    n: 'Железный Периметр',
    i: '🛡️',
    desc: '+30% к защите Штурмовиков и прочности ворот',
    bonus: { atk: 0.95, def: 1.30, spd: 0.90 }
  },
  flank: {
    id: 'flank',
    n: 'Мобильный Рейд',
    i: '⚡',
    desc: '+35% к скорости отрядов на ТВД и крит. урону',
    bonus: { atk: 1.15, def: 0.95, spd: 1.35 }
  }
};
function getTroopTier(barLv){
  const lv = barLv || 1;
  if(lv >= 15) return { t: 'T5', n: 'Спецназ Авангарда', mult: 2.5, color: '#c084fc' };
  if(lv >= 10) return { t: 'T4', n: 'Элита Порта', mult: 2.0, color: '#fbbf24' };
  if(lv >= 6)  return { t: 'T3', n: 'Ветераны Пустоши', mult: 1.6, color: '#38bdf8' };
  if(lv >= 3)  return { t: 'T2', n: 'Ополчение Стен', mult: 1.3, color: '#4ade80' };
  return { t: 'T1', n: 'Новобранцы', mult: 1.0, color: '#94a3b8' };
}
G.setArmyFormation = function(formationId){
  initTroopsState();
  if(!ARMY_FORMATIONS[formationId]) return;
  G.S.armyFormation = formationId;
  const form = ARMY_FORMATIONS[formationId];
  if(G.save) G.save();
  try { G.snd("click"); } catch(e){}
  G.toast(`🚩 Тактическая формация изменена: ${form.i} ${form.n}!`);
  if(G.rPanel) G.rPanel();
};
G.trainTroops = function(type, amt){
  initTroopsState();
  const s = G.S;
  if(s.training) return G.toast('⏳ Казармы уже заняты обучением отряда!');
  const cfg = TROOP_TYPES[type];
  if(!cfg) return;
  const count = amt || 25;
  const foodCost = (cfg.cost.food || 10) * count;
  const woodCost = (cfg.cost.wood || 0) * count;
  const metalCost = (cfg.cost.metal || 0) * count;
  if((s.res.food || 0) < foodCost || (s.res.wood || 0) < woodCost || (s.res.metal || 0) < metalCost){
    return G.toast(`❌ Не хватает ресурсов! Нужно: 🍖${foodCost}, 🪵${woodCost}, ⚙${metalCost}`);
  }
  s.res.food -= foodCost;
  s.res.wood -= woodCost;
  s.res.metal -= metalCost;
  const baseTime = (cfg.cost.time || 10) * count;
  const techMult = 1 / (1 + ((s.techs && s.techs.tech_train) ? s.techs.tech_train * 0.1 : 0));
  const durationSec = Math.max(3, Math.round(baseTime * techMult));
  s.training = {
    type,
    amt: count,
    end: Date.now() + (durationSec * 1000),
    totalSec: durationSec
  };
  if(G.save) G.save();
  try { G.snd("click"); } catch(e){}
  G.toast(`⚔ Начат набор: ${cfg.i} ${cfg.n} (${count} бойцов)`);
  if(G.rPanel) G.rPanel();
};
G.finishTrainingGems = function(){
  initTroopsState();
  const s = G.S;
  if(!s.training) return;
  if((s.res.gems || 0) < 15) return G.toast('❌ Нужно 15 💎 для ускорения!');
  s.res.gems -= 15;
  s.troops[s.training.type] = (s.troops[s.training.type] || 0) + s.training.amt;
  const doneName = TROOP_TYPES[s.training.type].n;
  const doneAmt = s.training.amt;
  s.training = null;
  if(G.save) G.save();
  try { G.snd("victory"); } catch(e){}
  G.toast(`🎉 Набор завершён: +${doneAmt} ${doneName} встали в строй!`);
  if(G.rPanel) G.rPanel();
};
G.trainAllClassesBatch = function(countPerClass){
  initTroopsState();
  const s = G.S;
  if(s.training) return G.toast('⏳ Казармы уже заняты обучением!');
  const amt = countPerClass || 25;
  let totalFood = 0, totalWood = 0, totalMetal = 0;
  for(let k in TROOP_TYPES){
    const cfg = TROOP_TYPES[k];
    totalFood += (cfg.cost.food || 0) * amt;
    totalWood += (cfg.cost.wood || 0) * amt;
    totalMetal += (cfg.cost.metal || 0) * amt;
  }
  if((s.res.food || 0) < totalFood || (s.res.wood || 0) < totalWood || (s.res.metal || 0) < totalMetal){
    return G.toast(`❌ Нужно: 🍖${totalFood}, 🪵${totalWood}, ⚙${totalMetal}`);
  }
  s.res.food -= totalFood;
  s.res.wood -= totalWood;
  s.res.metal -= totalMetal;
  s.troops.melee = (s.troops.melee || 0) + amt;
  s.troops.ranged = (s.troops.ranged || 0) + amt;
  s.troops.cavalry = (s.troops.cavalry || 0) + amt;
  if(G.save) G.save();
  try { G.snd("victory"); } catch(e){}
  G.toast(`🏆 Всеобщая мобилизация! +${amt} Штурмовиков, +${amt} Стрелков, +${amt} Рейдеров в строю!`);
  if(G.rPanel) G.rPanel();
};
G.healAllWoundedTroops = function(){
  initTroopsState();
  const s = G.S;
  const w = (s.hospital && s.hospital.wounded) || { ranged: 0, melee: 0, cavalry: 0 };
  const totalWounded = (w.ranged || 0) + (w.melee || 0) + (w.cavalry || 0);
  if(totalWounded <= 0){
    G.toast('💚 В госпитале нет раненых бойцов. Все здоровы!');
    return;
  }
  const costFood = totalWounded * 8;
  if((s.res.food || 0) < costFood){
    return G.toast(`❌ Не хватает провианта для перевязок! Нужно: 🍖${costFood}`);
  }
  s.res.food -= costFood;
  for(let k in w){
    s.troops[k] = (s.troops[k] || 0) + (w[k] || 0);
    w[k] = 0;
  }
  if(G.save) G.save();
  try { G.snd("heal"); } catch(e){}
  G.toast(`💉 Госпиталь вылечил ${totalWounded} раненых бойцов! Они вернулись в строй.`);
  if(G.rPanel) G.rPanel();
};
function checkTrainingTick(){
  if(!G.S || !G.S.training) return;
  const s = G.S;
  if(Date.now() >= s.training.end){
    s.troops[s.training.type] = (s.troops[s.training.type] || 0) + s.training.amt;
    const doneName = TROOP_TYPES[s.training.type].n;
    const doneAmt = s.training.amt;
    s.training = null;
    if(G.save) G.save();
    try { G.snd("reward"); } catch(e){}
    G.toast(`🎉 Обучение бойцов завершено: +${doneAmt} ${doneName}!`);
    if(s.tab === 'heroes' && s.sub === 'troops' && G.rPanel) G.rPanel();
  }
}
function rTroops(){
  initTroopsState();
  const s = G.S;
  const barLv = (s.bld && s.bld.bar) || 1;
  const tier = getTroopTier(barLv);
  const totalArmy = (s.troops.ranged || 0) + (s.troops.melee || 0) + (s.troops.cavalry || 0);
  const curForm = ARMY_FORMATIONS[s.armyFormation || 'balanced'] || ARMY_FORMATIONS.balanced;
  const w = (s.hospital && s.hospital.wounded) || { ranged: 0, melee: 0, cavalry: 0 };
  const totalWounded = (w.ranged || 0) + (w.melee || 0) + (w.cavalry || 0);
  let trainHTML = '';
  if(s.training){
    const leftSec = Math.max(0, Math.ceil((s.training.end - Date.now()) / 1000));
    const cfg = TROOP_TYPES[s.training.type] || { i: '⚔', n: 'Отряд' };
    const pct = Math.min(100, Math.round((1 - leftSec / (s.training.totalSec || 1)) * 100));
    trainHTML = `
      <div class="cd hl" style="margin-bottom:10px; background:linear-gradient(135deg,#1e293b,#0f172a); border:1px solid #38bdf8; border-radius:8px; padding:10px;">
        <div class="ch" style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
          <span class="ct" style="color:#7dd3fc; font-weight:bold;">⏳ Обучение в казармах</span>
          <span class="bg bg-g" style="font-size:11px; padding:2px 6px; border-radius:4px; background:rgba(34,197,94,0.2); color:#4ade80;">${pct}%</span>
        </div>
        <div class="cdd" style="margin:4px 0; font-size:11.5px; color:#cbd5e1;">
          Подготовка: <b>${cfg.i} ${cfg.n} (${s.training.amt} бойцов)</b> · Осталось: ${leftSec} сек.
        </div>
        <div style="background:#090d12; height:8px; border-radius:4px; overflow:hidden; margin:6px 0;">
          <div style="background:linear-gradient(90deg,#f59e0b,#22c55e); height:100%; width:${pct}%;"></div>
        </div>
        <button class="bgn bf" style="margin-top:6px; padding:6px; font-size:11px; background:linear-gradient(90deg,#0284c7,#38bdf8); color:#fff; border:none; border-radius:4px; cursor:pointer;" onclick="G.finishTrainingGems()">⚡ Завершить мгновенно · 15 💎</button>
      </div>`;
  }
  return `
    <div class="sec">⚔ АРМИЯ И КАЗАРМЫ · ${tier.t} (${tier.n.toUpperCase()})</div>
    <!-- Шапка статуса армии -->
    <div style="display:flex; justify-content:space-between; align-items:center; background:linear-gradient(135deg,rgba(20,24,32,0.95),rgba(15,23,42,0.95)); border:1px solid #334155; border-radius:8px; padding:10px 12px; margin-bottom:10px;">
      <div>
        <span style="font-size:14px; font-weight:900; color:${tier.color};">Ранг войск: ${tier.t}</span>
        <br><small style="color:#94a3b8;">Казарма ур. ${barLv} (мощь ×${tier.mult})</small>
      </div>
      <div style="text-align:right;">
        <span style="font-size:15px; font-weight:900; color:#f8fafc;">👥 ${totalArmy.toLocaleString()}</span>
        <br><small style="color:#64748b;">Бойцов в строю</small>
      </div>
    </div>
    <!-- Тактический Треугольник Противодействия -->
    <div style="background:rgba(15,23,42,0.8); border:1px solid #334155; border-radius:8px; padding:10px; margin-bottom:10px;">
      <div style="font-size:11.5px; font-weight:bold; color:#fbbf24; margin-bottom:6px; display:flex; align-items:center; gap:6px;">
        <span>🔄</span> Боевой Треугольник Противодействия (TWD Survivors)
      </div>
      <div style="display:grid; grid-template-columns:1fr 1fr 1fr; gap:6px; font-size:10px; text-align:center;">
        <div style="background:rgba(59,130,246,0.15); border:1px solid rgba(59,130,246,0.4); padding:6px 4px; border-radius:6px; color:#93c5fd;">
          <b>🛡️ Штурмовики</b><br>бьют 🎯 Стрелков<br><span style="color:#4ade80;">+30% урона</span>
        </div>
        <div style="background:rgba(245,158,11,0.15); border:1px solid rgba(245,158,11,0.4); padding:6px 4px; border-radius:6px; color:#fde68a;">
          <b>🎯 Стрелки</b><br>бьют 🏍️ Рейдеров<br><span style="color:#4ade80;">+30% урона</span>
        </div>
        <div style="background:rgba(168,85,247,0.15); border:1px solid rgba(168,85,247,0.4); padding:6px 4px; border-radius:6px; color:#e9d5ff;">
          <b>🏍️ Рейдеры</b><br>бьют 🛡️ Штурмовиков<br><span style="color:#4ade80;">+30% урона</span>
        </div>
      </div>
    </div>
    <!-- Выбор Тактической Формации -->
    <div style="background:rgba(15,23,42,0.8); border:1px solid #334155; border-radius:8px; padding:10px; margin-bottom:10px;">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
        <div style="font-size:12px; font-weight:bold; color:#7dd3fc;">🚩 Тактическая Формация:</div>
        <div style="font-size:11px; color:#fbbf24; font-weight:bold;">${curForm.i} ${curForm.n}</div>
      </div>
      <div style="font-size:10.5px; color:#94a3b8; margin-bottom:8px;">${curForm.desc}</div>
      <div style="display:grid; grid-template-columns:1fr 1fr; gap:6px;">
        ${Object.values(ARMY_FORMATIONS).map(f => `
          <button onclick="G.setArmyFormation('${f.id}')" style="background:${s.armyFormation===f.id?'linear-gradient(90deg,#0284c7,#0ea5e9)':'#1e293b'}; color:#fff; border:1px solid ${s.armyFormation===f.id?'#38bdf8':'#475569'}; padding:6px; border-radius:6px; font-size:10.5px; cursor:pointer; text-align:left;">
            ${f.i} <b>${f.n}</b>
          </button>
        `).join('')}
      </div>
    </div>
    ${trainHTML}
    <!-- Блок Госпиталя и Быстрого Лечения -->
    ${totalWounded > 0 ? `
      <div style="background:linear-gradient(135deg,#3b1a1a,#1e1212); border:1px solid #ef4444; border-radius:8px; padding:10px; margin-bottom:10px;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
          <div style="font-size:12px; font-weight:bold; color:#fca5a5;">🏥 Полевой Госпиталь: ${totalWounded} раненых</div>
          <div style="font-size:10.5px; color:#f87171;">🛡️${w.melee} 🎯${w.ranged} 🏍️${w.cavalry}</div>
        </div>
        <button onclick="G.healAllWoundedTroops()" style="width:100%; background:linear-gradient(90deg,#dc2626,#ef4444); color:#fff; border:none; padding:8px; border-radius:6px; font-weight:bold; font-size:11.5px; cursor:pointer;">💊 Вылечить всех раненых (🍖${totalWounded*8})</button>
      </div>
    ` : ''}
    <!-- Кнопка мобилизации всех классов -->
    <div style="margin-bottom:10px;">
      <button onclick="G.trainAllClassesBatch(25)" style="width:100%; background:linear-gradient(90deg,#15803d,#22c55e); color:#fff; border:none; padding:9px; border-radius:6px; font-weight:bold; font-size:12px; cursor:pointer; box-shadow:0 4px 12px rgba(34,197,94,0.3);">
        ⚔ Всеобщий набор армии (+25 каждого класса · 🍖1500)
      </button>
    </div>
    <!-- Карточки 3 классов войск -->
    <div class="g1" style="display:flex; flex-direction:column; gap:8px;">
      ${Object.entries(TROOP_TYPES).map(([k, cfg]) => {
        const count = s.troops[k] || 0;
        const isTraining = !!s.training;
        return `
          <div class="cd" style="background:#161b22; border:1px solid #30363d; border-radius:8px; padding:10px;">
            <div class="ch" style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;">
              <span class="ct" style="font-size:13px; font-weight:bold; color:#f1f5f9;">${cfg.i} ${cfg.n} (${tier.t})</span>
              <span class="bg bg-gn" style="font-size:10.5px; padding:2px 6px; border-radius:4px; background:rgba(34,197,94,0.15); color:#4ade80; border:1px solid rgba(34,197,94,0.3);">В строю: ${count} чел.</span>
            </div>
            <div class="cdd" style="font-size:11px; color:#cbd5e1; margin:2px 0;">${cfg.desc}</div>
            <div style="font-size:10px; color:#38bdf8; margin:2px 0;">${cfg.counterText}</div>
            <div class="cc" style="font-size:10px; color:#94a3b8; margin:3px 0;">
              ⚔ Атака: ${(cfg.atk * tier.mult).toFixed(1)} · 🛡 Защита: ${(cfg.def * tier.mult).toFixed(1)} · 🏃 Скорость: ${cfg.spd}x · 👤 Синергия: ${cfg.synergyHero}
            </div>
            <div style="display:flex; gap:6px; margin-top:6px;">
              <button class="bp2" style="flex:1; font-size:10.5px; padding:7px; background:#1e293b; color:#cbd5e1; border:1px solid #475569; border-radius:4px; cursor:pointer;" ${isTraining?'disabled':''} onclick="G.trainTroops('${k}', 25)">Нанять 25 (🍖${cfg.cost.food*25})</button>
              <button class="bgn" style="flex:1; font-size:10.5px; padding:7px; background:#0284c7; color:#fff; border:none; border-radius:4px; cursor:pointer;" ${isTraining?'disabled':''} onclick="G.trainTroops('${k}', 50)">Нанять 50 (🍖${cfg.cost.food*50})</button>
            </div>
          </div>`;
      }).join('')}
    </div>
  `;
}
if(!G.SUBS.heroes.includes('troops')){
  G.SUBS.heroes.push('troops');
  G.SL.troops = '⚔Армия';
}
const prevRPanelTroops = G.rPanel;
G.rPanel = function(){
  const t = document.getElementById('pn');
  const tab = this.S ? this.S.tab : null;
  const sub = this.S ? this.S.sub : null;
  if(tab === 'heroes' && sub === 'troops'){
    if(t){
      t.dataset.sub = sub;
      t.innerHTML = rTroops();
    }
    return;
  }
  prevRPanelTroops.apply(this, arguments);
};
const prevTickTroops = G.tick;
if(prevTickTroops){
  G.tick = function(){
    prevTickTroops.apply(this, arguments);
    checkTrainingTick();
  };
}
const prevCalcPowTroops = G.calcPow;
if(prevCalcPowTroops){
  G.calcPow = function(){
    prevCalcPowTroops.apply(this, arguments);
    if(!this.S) return;
    initTroopsState();
    if(this.S.troops){
      const barLv = (this.S.bld && this.S.bld.bar) || 1;
      const tier = getTroopTier(barLv);
      const form = ARMY_FORMATIONS[this.S.armyFormation || 'balanced'] || ARMY_FORMATIONS.balanced;
      let wuMult = 1.0;
      if(this.S.specialists && this.S.specialists.spec_wu && this.S.specialists.spec_wu.assigned){
        wuMult = 1.15;
      }
      const troopPow = ((this.S.troops.ranged || 0) * 16 + (this.S.troops.melee || 0) * 14 + (this.S.troops.cavalry || 0) * 18) * tier.mult * wuMult * (form.bonus.atk || 1.0);
      this.S.power = Math.round((this.S.power || 0) + troopPow);
    }
  };
}
window.twdTroops = {
  initTroopsState,
  TROOP_TYPES,
  ARMY_FORMATIONS,
  getTroopTier
};
initTroopsState();
})();;
/* Script #22 (id=twd-sanc-js) */
/* F-65: Святилища Региона, Разведка и Клановые Осады (The Walking Dead: Survivors replica)
   4 Великих Святилища, Отчёты разведки, Клановые марши осады, Баффы оккупации */
(function(){
'use strict';
if(typeof window==='undefined'||!window.G)return;
const G=window.G;
const SANCTUARIES=[
  {
    id:'sanc_north',
    n:'Цитадель Спасителей',
    i:'🏰',
    pos:{x:1150, y:180},
    pow:35000,
    boss:'Неган',
    buff:'⚔ Урон армии +20% во всех битвах',
    desc:'Главная база рейдеров на севере. Тяжёлые укрепления, пулемётные вышки и элитный гарнизон.',
    rw:'1500 💎 · 800 🪙 · Бафф Атаки'
  },
  {
    id:'sanc_east',
    n:'Нефтяной Терминал «Апекс»',
    i:'🛢',
    pos:{x:2050, y:1100},
    pow:28000,
    boss:'Комендант Бруно',
    buff:'🧲 Добыча ресурсов +30%, марш +40%',
    desc:'Крупнейший топливный узел региона. Контроль даёт преимущество в скорости снабжения.',
    rw:'1200 💎 · 600 🪙 · Бафф Логистики'
  },
  {
    id:'sanc_west',
    n:'Радиокомплекс «Аврора»',
    i:'📡',
    pos:{x:280, y:950},
    pow:22000,
    boss:'Капитан Воронов',
    buff:'⚡ Регенерация энергии +30%, разведка +50%',
    desc:'Мощный коротковолновый передатчик. Позволяет сканировать весь сектор.',
    rw:'1000 💎 · 500 🪙 · Бафф Связи'
  },
  {
    id:'sanc_south',
    n:'Укрепрайон Голиафа',
    i:'🌋',
    pos:{x:1450, y:1950},
    pow:45000,
    boss:'Голиаф-Мутант',
    buff:'🛡 Прочность стены +50%, защита +25%',
    desc:'Бункерная цитадель в южном секторе залива. Защищена тяжёлой бронёй.',
    rw:'2500 💎 · 1200 🪙 · Бафф Защиты'
  }
];
function initSancState(){
  if(!G.S)return;
  const s=G.S;
  if(!s.sanctuaries){
    s.sanctuaries={
      sanc_north:{owner:null, capturedAt:0},
      sanc_east:{owner:null, capturedAt:0},
      sanc_west:{owner:null, capturedAt:0},
      sanc_south:{owner:null, capturedAt:0}
    };
  }
  if(!s.scoutReports) s.scoutReports={};
}
G.scoutTarget=function(targetId, type, name, reqPow){
  initSancState();
  const s=G.S;
  if((s.energy||0)<5) return G.toast('Нужно ⚡5 энергии для отправки разведчика!');
  s.energy-=5;
  const pow=reqPow||15000;
  const report={
    id:targetId,
    name:name||'Цель',
    type:type||'camp',
    time:Date.now(),
    pow:pow,
    ranged:Math.round(pow*0.35/12),
    melee:Math.round(pow*0.45/10),
    cavalry:Math.round(pow*0.20/14),
    food:Math.round(pow*1.8),
    wood:Math.round(pow*1.4),
    metal:Math.round(pow*0.8),
    gems:Math.round(pow*0.02)
  };
  s.scoutReports[targetId]=report;
  if(G.addMailReport){
    G.addMailReport({
      cat:'scout',
      title:'Разведка: '+name,
      icon:'🔭',
      text:'Разведывательный дозор передал данные об объекте «'+name+'». Оценочная мощь гарнизона: '+pow.toLocaleString()+' (Стрелков: '+report.troops.ranged+', Штурмовиков: '+report.troops.melee+', Рейдеров: '+report.troops.cavalry+'). Запасы на объекте: '+report.res.food+'🍖, '+report.res.wood+'🪵, '+report.res.metal+'⚙, '+report.res.gems+'💎.'
    });
  }
  G.toast('🔭 Разведчик вернулся с подробным отчётом!');
  G.snd('radar');
  G.showScoutModal(report);
};
G.showScoutModal=function(rep){
  const old=document.getElementById('scoutModal');
  if(old) old.remove();
  const m=document.createElement('div');
  m.id='scoutModal';
  m.className='mf-modal';
  m.innerHTML='<div class="mf-bg" onclick="document.getElementById(\'scoutModal\').remove()"></div>'
    +'<div class="mf-card" style="max-width:380px">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'
    +'<span style="font-size:14px;font-weight:900;color:#f8fafc">🔭 ОТЧЁТ ВОЕННОЙ РАЗВЕДКИ</span>'
    +'<button style="background:none;border:none;color:#94a3b8;font-size:18px;cursor:pointer" onclick="document.getElementById(\'scoutModal\').remove()">✕</button>'
    +'</div>'
    +'<div class="cd" style="margin-bottom:6px;background:rgba(15,23,42,.85)">'
    +'<div class="ch"><span class="ct">📍 '+rep.name+'</span><span class="bg bg-r">⚔ Мощь: '+rep.pow.toLocaleString()+'</span></div>'
    +'<div class="cdd" style="margin-top:4px">Состав гарнизона противника:</div>'
    +'<div class="cc" style="font-size:9.5px;color:#cbd5e1;margin:3px 0">'
    +'🎯 Стрелки: <b>'+rep.ranged+'</b> · 🛡 Штурмовики: <b>'+rep.melee+'</b> · 🐎 Рейдеры: <b>'+rep.cavalry+'</b>'
    +'</div>'
    +'<div class="cdd" style="margin-top:4px">Разведанные запасы ресурсов:</div>'
    +'<div class="cc" style="font-size:9.5px;color:#fbbf24;margin:3px 0">'
    +'🍖 '+rep.food+' · 🪵 '+rep.wood+' · ⚙ '+rep.metal+' · 💎 '+rep.gems
    +'</div>'
    +'</div>'
    +'<button class="bgn bf" style="padding:8px" onclick="document.getElementById(\'scoutModal\').remove()">Закрыть отчёт</button>'
    +'</div>';
  document.body.appendChild(m);
};
G.startSanctuarySiege=function(sancIdx){
  initSancState();
  const s=G.S;
  const target=SANCTUARIES[sancIdx];
  if(!target) return;
  if((s.energy||0)<25) return G.toast('Нужно ⚡25 энергии для осады Святилища!');
  if(!s.alliance) return G.toast('Осаду Святилища может объявить только участник альянса!');
  s.energy-=25;
  const myPow=s.power||1500;
  const allyFleetPow=15000*(s.clanTech?.atk||1);
  const totalSiegePow=myPow+allyFleetPow;
  if(totalSiegePow>=target.pow){
    s.sanctuaries[target.id].owner=s.alliance;
    s.sanctuaries[target.id].capturedAt=Date.now();
    s.gems=(s.gems||0)+1000;
    s.clanCoins=(s.clanCoins||0)+500;
    if(G.addMailReport){
      G.addMailReport({
        cat:'siege',
        title:'Триумф осады: '+target.n,
        icon:'👑',
        text:'Войска альянса успешно сломили оборону гарнизона '+target.boss+' ('+target.pow.toLocaleString()+')! Святилище перешло под контроль альянса. Получен региональный бафф: '+target.buff+'.',
        loot:{gems:1000}
      });
    }
    G.toast('👑 ПОБЕДА! Святилище «'+target.n+'» захвачено вашим альянсом! +1000💎 +500🪙');
    G.snd('win');
  }else{
    if(G.addMailReport){
      G.addMailReport({
        cat:'siege',
        title:'Поражение при осаде: '+target.n,
        icon:'💥',
        text:'Штурм святилища «'+target.n+'» захлебнулся под огнём гарнизона '+target.boss+'. Мощь отряда ('+totalSiegePow.toLocaleString()+') уступила защитникам ('+target.pow.toLocaleString()+'). Требуется мобилизация сил альянса.'
      });
    }
    G.toast('💥 Осада отбита гарнизоном '+target.boss+' ('+target.pow.toLocaleString()+'). Не хватило сил!');
    G.snd('hit');
  }
  G.rPanel();
};
function rSanctuaries(){
  initSancState();
  const s=G.S;
  const allyName=s.alliance?((G.ALLIANCES.find(a=>a.id===s.alliance)||{}).n||'Ваш альянс'):'Нет альянса';
  return '<div class="sec">🏛 ВЕЛИКИЕ СВЯТИЛИЩА РЕГИОНА</div>'
    +'<div class="cdd" style="margin-bottom:8px">Ключевые цитадели региона. Захват Святилища альянсом даёт постоянный бонус всем участникам общины.</div>'
    +'<div class="g1">'+SANCTUARIES.map((sanc,i)=>{
      const info=s.sanctuaries[sanc.id]||{};
      const isOwner=info.owner&&info.owner===s.alliance;
      const ownerName=info.owner?((G.ALLIANCES.find(a=>a.id===info.owner)||{}).n||info.owner):'Гарнизон Спасителей';
      return '<div class="cd '+(isOwner?'hl':'')+'">'
        +'<div class="ch"><span class="ct">'+sanc.i+' '+sanc.n+'</span><span class="bg '+(isOwner?'bg-gn':'bg-r')+'">'+(isOwner?'👑 Под контролем '+allyName:'Оккупация: '+ownerName)+'</span></div>'
        +'<div class="cdd" style="margin:2px 0">'+sanc.desc+'</div>'
        +'<div class="cc" style="font-size:9.5px;color:#4ade80;font-weight:700;margin:3px 0">✨ Бафф альянса: '+sanc.buff+'</div>'
        +'<div class="cc" style="font-size:9px;color:#fbbf24;margin:2px 0">🎁 Награда за взятие: '+sanc.rw+' · ⚔ Требуемая мощь: '+sanc.pow.toLocaleString()+'</div>'
        +'<div style="display:flex;gap:6px;margin-top:6px">'
        +'<button class="bs" style="flex:1;font-size:9.5px;padding:6px" onclick="G.scoutTarget(\''+sanc.id+'\',\'sanctuary\',\''+sanc.n+'\','+sanc.pow+')">🔭 Разведка (⚡5)</button>'
        +'<button class="bp2" style="flex:1.5;font-size:9.5px;padding:6px" onclick="G.startSanctuarySiege('+i+')">⚔ Начать осаду альянса (⚡25)</button>'
        +'</div></div>';
    }).join('')+'</div>';
}
if(!G.SUBS.map.includes('sanctuaries')){
  G.SUBS.map.push('sanctuaries');
  G.SL.sanctuaries='🏛Святилища';
}
const prevRPanelSanc=G.rPanel;
G.rPanel=function(){
  const t=document.getElementById('pn');
  const tab=this.S.tab;
  const sub=this.S.sub;
  if(tab==='map'&&sub==='sanctuaries'){
    if(t) t.dataset.sub=sub;
    t.innerHTML=rSanctuaries();
    return;
  }
  prevRPanelSanc.apply(this,arguments);
};
const prevCalcPowSanc=G.calcPow;
if(prevCalcPowSanc){
  G.calcPow=function(){
    prevCalcPowSanc.apply(this,arguments);
    initSancState();
    if(G.S&&G.S.sanctuaries&&G.S.alliance){
      if(G.S.sanctuaries.sanc_north?.owner===G.S.alliance){
        G.S.power=Math.round((G.S.power||0)*1.20);
      }
    }
  };
}
window.twdSanctuaries={
  initSancState,
  SANCTUARIES
};
})();;
/* Script #23 (id=twd-layout-js) */
/* F-66: Свободная планировка и перемещение зданий на 3D-базе (The Walking Dead: Survivors replica)
   Свободное перемещение, поворот на 90°, сетка 1.5м, сохранение в S.bldPositions */
(function(){
'use strict';
if(typeof window==='undefined'||!window.G)return;
const G=window.G;
const BLD_KEYS=['hq','farm','saw','wh','wrk','bar','hosp','lab','market','wt','wall'];
const BLD_NAMES={
  hq:'Ратуша', farm:'Ферма', saw:'Лесопилка', wh:'Склад', wrk:'Мастерская',
  bar:'Казарма', hosp:'Госпиталь', lab:'Лаборатория', market:'Рынок', wt:'Вышка', wall:'Стена'
};
const DEFAULT_POSITIONS={
  hq: {x:0, z:0, rot:0},
  farm: {x:-6, z:-11.7, rot:0},
  saw: {x:6, z:-11.7, rot:0},
  wh: {x:6, z:10.5, rot:0},
  hosp: {x:-6, z:10.5, rot:0},
  wrk: {x:6, z:-2, rot:0},
  bar: {x:-11.4, z:-5, rot:0},
  lab: {x:10.5, z:-1, rot:0},
  market: {x:-6, z:10.5, rot:0},
  wt: {x:-10.5, z:4, rot:0},
  wall: {x:0, z:13.5, rot:0}
};
let selectedBld='farm';
let isLayoutMode=false;
function initLayoutState(){
  if(!G.S)return;
  if(!G.S.bldPositions){
    G.S.bldPositions=JSON.parse(JSON.stringify(DEFAULT_POSITIONS));
  }
}
G.apply3DLayout=function(){
  initLayoutState();
  const s=G.S;
  if(!s||!s.bldPositions) return;
  try {
    const iframe=document.querySelector('#artContainer iframe');
    if(!iframe||!iframe.contentWindow) return;
    const w=iframe.contentWindow;
    const buildings=w.buildings||(w.baseArt&&w.baseArt.buildings)||[];
    buildings.forEach(b=>{
      const type=b.userData?.type||b.userData?.gameKey;
      if(type&&s.bldPositions[type]){
        const p=s.bldPositions[type];
        b.position.x=p.x;
        b.position.z=p.z;
        if(p.rot!=null) b.rotation.y=p.rot;
      }
    });
  } catch(e) {
    console.warn('[Layout apply error]', e);
  }
};
G.moveSelectedBuilding=function(dx, dz){
  initLayoutState();
  const s=G.S;
  if(!selectedBld||!s.bldPositions[selectedBld]) return;
  const cur=s.bldPositions[selectedBld];
  cur.x=Math.max(-12.5, Math.min(12.5, Math.round((cur.x+dx)*10)/10));
  cur.z=Math.max(-12.5, Math.min(12.5, Math.round((cur.z+dz)*10)/10));
  G.apply3DLayout();
  G.updateLayoutUI();
};
G.rotateSelectedBuilding=function(){
  initLayoutState();
  const s=G.S;
  if(!selectedBld||!s.bldPositions[selectedBld]) return;
  const cur=s.bldPositions[selectedBld];
  cur.rot=((cur.rot||0)+Math.PI/2)%(Math.PI*2);
  G.apply3DLayout();
  G.updateLayoutUI();
  G.toast('🔄 '+BLD_NAMES[selectedBld]+' повернуто на 90°');
};
G.resetLayoutToDefault=function(){
  initLayoutState();
  G.S.bldPositions=JSON.parse(JSON.stringify(DEFAULT_POSITIONS));
  G.apply3DLayout();
  G.updateLayoutUI();
  G.toast('🔄 Планировка базы сброшена к исходной');
};
G.selectLayoutBuilding=function(key){
  selectedBld=key;
  G.updateLayoutUI();
  G.toast('Выбрано: '+BLD_NAMES[key]);
};
G.toggleLayoutMode=function(force){
  initLayoutState();
  isLayoutMode=typeof force==='boolean'?force:!isLayoutMode;
  let modal=document.getElementById('layoutModal');
  if(!isLayoutMode){
    if(modal) modal.remove();
    G.save&&G.save(!0);
    G.toast('💾 Планировка сохранена');
    return;
  }
  if(!modal){
    modal=document.createElement('div');
    modal.id='layoutModal';
    modal.style.cssText='position:fixed;bottom:70px;left:8px;right:8px;max-width:400px;margin:0 auto;z-index:200;background:rgba(18,24,32,.96);border:2px solid #e8c547;border-radius:12px;padding:10px;box-shadow:0 10px 30px #000c;color:#f8fafc;font-family:system-ui';
    document.body.appendChild(modal);
  }
  G.updateLayoutUI();
  G.apply3DLayout();
};
G.updateLayoutUI=function(){
  const modal=document.getElementById('layoutModal');
  if(!modal||!isLayoutMode) return;
  initLayoutState();
  const curPos=(G.S.bldPositions&&G.S.bldPositions[selectedBld])||{x:0,z:0,rot:0};
  const deg=Math.round(((curPos.rot||0)*180)/Math.PI);
  modal.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">'
    +'<span style="font-size:12px;font-weight:900;color:#e8c547">📐 РЕЖИМ ПЛАНИРОВКИ БАЗЫ</span>'
    +'<button style="background:#22c55e;color:#000;font-weight:900;font-size:10px;padding:4px 8px;border-radius:5px;border:none;cursor:pointer" onclick="G.toggleLayoutMode(false)">💾 Готово</button>'
    +'</div>'
    +'<div style="margin-bottom:6px">'
    +'<label style="font-size:9.5px;color:#94a3b8">Выберите здание для перемещения:</label>'
    +'<select style="width:100%;margin-top:2px;padding:6px;border-radius:6px;background:#0f172a;border:1px solid #334155;color:#fff;font-weight:700;font-size:11px" onchange="G.selectLayoutBuilding(this.value)">'
    +BLD_KEYS.map(k=>'<option value="'+k+'" '+(k===selectedBld?'selected':'')+'>'+BLD_NAMES[k]+' (X:'+((G.S.bldPositions[k]||{}).x||0)+', Z:'+((G.S.bldPositions[k]||{}).z||0)+')</option>').join('')
    +'</select>'
    +'</div>'
    +'<div style="display:flex;gap:6px;align-items:center;justify-content:center;margin:6px 0">'
    +'<div style="display:grid;grid-template-columns:36px 36px 36px;gap:4px">'
    +'<div></div><button class="bp2" style="padding:8px 0;font-size:14px" onclick="G.moveSelectedBuilding(0, -1.5)">⬆</button><div></div>'
    +'<button class="bp2" style="padding:8px 0;font-size:14px" onclick="G.moveSelectedBuilding(-1.5, 0)">⬅</button>'
    +'<button class="bgn" style="padding:8px 0;font-size:12px" onclick="G.rotateSelectedBuilding()">🔄</button>'
    +'<button class="bp2" style="padding:8px 0;font-size:14px" onclick="G.moveSelectedBuilding(1.5, 0)">➡</button>'
    +'<div></div><button class="bp2" style="padding:8px 0;font-size:14px" onclick="G.moveSelectedBuilding(0, 1.5)">⬇</button><div></div>'
    +'</div>'
    +'<div style="flex:1;font-size:9.5px;line-height:1.4;color:#cbd5e1;padding-left:8px">'
    +'<b>'+BLD_NAMES[selectedBld]+'</b><br>'
    +'X: '+curPos.x+' · Z: '+curPos.z+'<br>'
    +'Угол: '+deg+'°<br>'
    +'<button class="bs" style="margin-top:4px;padding:3px 6px;font-size:8.5px;color:#f87171" onclick="G.resetLayoutToDefault()">Сброс</button>'
    +'</div>'
    +'</div>';
};
function injectLayoutButton(){
  const bar=document.getElementById('mainBaseBar');
  if(!bar||document.getElementById('mainLayoutBtn')) return;
  const btn=document.createElement('button');
  btn.id='mainLayoutBtn';
  btn.type='button';
  btn.textContent='📐 Планировка';
  btn.style.cssText='background:#1a2330;border:1px solid #e8c547;color:#f8e7b0;font-weight:800;border-radius:6px';
  btn.onclick=()=>G.toggleLayoutMode();
  bar.insertBefore(btn, bar.lastElementChild);
}
if(typeof document!=='undefined'){
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded', ()=>{
      injectLayoutButton();
      setTimeout(G.apply3DLayout, 2000);
    });
  }else{
    injectLayoutButton();
    setTimeout(G.apply3DLayout, 2000);
  }
}
const prevTab=G.tab;
if(prevTab){
  G.tab=function(tab, sub){
    prevTab.apply(this,arguments);
    if(tab==='base'){
      setTimeout(G.apply3DLayout, 500);
    }else if(isLayoutMode){
      G.toggleLayoutMode(false);
    }
  };
}
window.twdLayout={
  initLayoutState,
  DEFAULT_POSITIONS,
  BLD_KEYS,
  BLD_NAMES
};
})();;
