G.boostProductionNode=function(type){
  const s=G.S;
  initTradeLogisticsState();
  if((s.energy||0)<15){
    return G.toast('Нужно ⚡15 энергии для запуска форсированного режима!');
  }
  s.energy-=15;
  if(type==='farm'){
    s.farmBoostUntil=Date.now()+7200000; // 2 часа
    G.toast('⚡ Форсированная гидропоника запущена (+50% еды на 2 часа)!');
  }else if(type==='saw'){
    s.sawBoostUntil=Date.now()+7200000; // 2 часа
    G.toast('⚡ Турбо-пилорамы запущены (+50% дерева на 2 часа)!');
  }else if(type==='vault'){
    s.vaultBoostUntil=Date.now()+7200000; // 2 часа
    G.toast('🛡 Складской бункер запечатан (100% защита от грабежа)!');
  }
  G.snd('click');
  G.rPanel();
};
