        +'<div style="font-size:9.5px;color:#cbd5e1">'
        +'Отдать: ' + Object.entries(d.pay).map(([k,v])=>(k==='wood'?'🪵':k==='food'?'🍖':'⚙')+v).join(' ')
        +' ➔ Получить: ' + Object.entries(d.get).map(([k,v])=>(k==='metal'?'⚙':k==='gems'?'💎':k==='energy'?'⚡':k==='wood'?'🪵':'🍖')+v).join(' ')
        +'</div>'
        +(isDone
          ?'<span style="font-size:9px;color:#22c55e;font-weight:800">✅ Совершено</span>'
          :'<button class="'+(canPay?'bp2':'bs')+'" style="font-size:9.5px;padding:4px 10px" '+(canPay?'':'disabled')+' onclick="G.tradeCaravanDeal('+idx+')">Обменять</button>'
        )
