const prevOpenArtBld4=window.openArtBuilding;
if(prevOpenArtBld4){
  window.openArtBuilding=function(k){
    const lvl=(G.S&&G.S.bld&&G.S.bld[k])||0;
    if(lvl===0){
      G.tab('base','buildings');
      G.focusBuilding(k);
      const bpan=document.getElementById('bpan');
      if(bpan){
        bpan.classList.remove('col');
        bpan.classList.remove('exp');
      }
      return;
    }
    if(k==='market'){
      G.tab('base','trade');
      G.toast('🏪 Торговый пост купца Рашида');
      return;
    }
    if(k==='wh'){
      G.tab('base','vault');
      G.toast('📦 Складской комплекс и сейф-бункер');
      return;
    }
    if(k==='farm'){
      G.tab('base','farmprod');
      G.toast('🌾 Агрокомплекс и тепличные хозяйства');
      return;
    }
    if(k==='saw'){
      G.tab('base','sawprod');
      G.toast('🪵 Механизированный лесопильный узел');
      return;
    }
    return prevOpenArtBld4.apply(this, arguments);
  };
}
