function initScoutsTalentsDecreesState(){
  if(!G.S) return;
  const s = G.S;
  if(!s.scouts){
    s.scouts = {
      activeMissions: {}, // { sectorId: { startTime, endTime, scoutId } }
      exploredSectors: {}, // { sectorId: { explored: true, looted: false } }
      totalExpeditions: 0
    };
  }
  if(!s.talents){
    s.talents = {
      points: 5,
      spent: 0,
      skills: {},
      cooldowns: {},
      activeBuffs: {}
    };
  }
  const hqLevel = typeof s.hq === 'object' ? (s.hq.lv || 1) : (Number(s.hq) || 1);
  const powerVal = typeof s.power === 'number' ? s.power : 30;
  s.talents.points = Math.max(5, hqLevel + Math.floor(powerVal / 50));
  if(!s.decrees){
    s.decrees = {
      activeDecree: null,
      cooldowns: {}
    };
  }
}
G.openScoutsUI = function(){
  initScoutsTalentsDecreesState();
  if(G.S) G.S.sub = 'scouts';
  if(G.rPanel) G.rPanel();
};
G.startScoutExpedition = function(sectorId){
  initScoutsTalentsDecreesState();
  const s = G.S;
  if(!s || !s.scouts) return;
  const sec = SCOUT_SECTORS.find(x => x.id === sectorId);
  if(!sec){
    G.toast('❌ Неизвестный сектор');
    return;
  }
  if(s.scouts.activeMissions[sectorId]){
    G.toast('⏳ Разведчик уже в пути в этот сектор!');
    return;
  }
  if((s.energy || 0) < 10){
    G.toast('❌ Недостаточно ⚡ энергии (нужно 10)');
    return;
  }
  s.energy -= 10;
  const now = Date.now();
  const speedBonus = 1 + ((s.talents && s.talents.skills && s.talents.skills['t_scout_spd']) || 0) * 0.15;
  const durationSec = Math.round(sec.scoutTime / speedBonus);
  s.scouts.activeMissions[sectorId] = {
    startTime: now,
    endTime: now + durationSec * 1000,
    sectorId: sectorId
  };
  s.scouts.totalExpeditions = (s.scouts.totalExpeditions || 0) + 1;
  if(G.save) G.save();
  G.toast('🏍 Разведчик на багги отправлен в ' + sec.name + ' (' + durationSec + ' сек)');
  if(G.rPanel) G.rPanel();
};
G.rushScoutExpedition = function(sectorId){
  initScoutsTalentsDecreesState();
  const s = G.S;
  if(!s || !s.scouts) return;
  const mission = s.scouts.activeMissions[sectorId];
  if(!mission){
    G.toast('❌ Нет активной экспедиции');
    return;
  }
  if((s.gems || 0) < 5){
    G.toast('❌ Нужно 5 💎 кристаллов для форсирования');
    return;
  }
  s.gems -= 5;
  mission.endTime = Date.now() - 1000; // Мгновенное завершение
  if(G.save) G.save();
  G.toast('⚡ Разведка форсирована!');
  if(G.rPanel) G.rPanel();
};
G.claimScoutLoot = function(sectorId){
  initScoutsTalentsDecreesState();
  const s = G.S;
  if(!s || !s.scouts) return;
  const sec = SCOUT_SECTORS.find(x => x.id === sectorId);
  if(!sec) return;
  const mission = s.scouts.activeMissions[sectorId];
  if(mission && mission.endTime > Date.now()){
    G.toast('⏳ Разведчик еще не вернулся с задания!');
    return;
  }
  delete s.scouts.activeMissions[sectorId];
  s.scouts.exploredSectors[sectorId] = { explored: true, looted: true, date: Date.now() };
  let rewardText = [];
  if(sec.rewards.metal){ s.metal = (s.metal || 0) + sec.rewards.metal; rewardText.push(`+${sec.rewards.metal} ⚙ Металла`); }
  if(sec.rewards.wood){ s.wood = (s.wood || 0) + sec.rewards.wood; rewardText.push(`+${sec.rewards.wood} 🪵 Дерева`); }
  if(sec.rewards.food){ s.food = (s.food || 0) + sec.rewards.food; rewardText.push(`+${sec.rewards.food} 🍖 Еды`); }
  if(sec.rewards.energy){ s.energy = Math.min((s.maxEnergy || 120), (s.energy || 0) + sec.rewards.energy); rewardText.push(`+${sec.rewards.energy} ⚡ Энергии`); }
  if(sec.rewards.gems){ s.gems = (s.gems || 0) + sec.rewards.gems; rewardText.push(`+${sec.rewards.gems} 💎 Кристаллов`); }
  if(sec.rewards.xp){ s.xp = (s.xp || 0) + sec.rewards.xp; rewardText.push(`+${sec.rewards.xp} XP`); }
  if(G.addMailReport){
    G.addMailReport('scout', `Разведка: ${sec.name}`, `Разведотряд на легком багги успешно исследовал ${sec.name} и доставил ценные трофеи на базу.`, sec.rewards);
  }
  if(G.save) G.save();
  G.toast('🎉 Награды получены: ' + rewardText.join(', '));
  if(G.rPanel) G.rPanel();
};
