G.assignWorker = function(stationId, workerId){
  initWorkersTowersEventsState();
  const s = G.S;
  if(!s || !s.workers || !s.workers.assignments) return;
  for(let st in s.workers.assignments){
    if(s.workers.assignments[st] === workerId){
      delete s.workers.assignments[st];
    }
  }
  s.workers.assignments[stationId] = workerId;
  const w = BASE_WORKERS.find(x => x.id === workerId);
  const st = WORKER_STATIONS.find(x => x.id === stationId);
  if(G.save) G.save();
  G.toast(`👷 ${w ? w.name : 'Рабочий'} назначен на пост «${st ? st.name : stationId}»!`);
  if(G.rPanel) G.rPanel();
};
G.unassignWorker = function(stationId){
  initWorkersTowersEventsState();
  const s = G.S;
  if(!s || !s.workers || !s.workers.assignments) return;
  delete s.workers.assignments[stationId];
  const st = WORKER_STATIONS.find(x => x.id === stationId);
  if(G.save) G.save();
  G.toast(`Специалист отозван с поста «${st ? st.name : stationId}»`);
  if(G.rPanel) G.rPanel();
};
