G.craftHeroRelic = function(relicId){
  initRelicsBarricadesBountiesState();
  const s = G.S;
  if(!s || !s.relics) return;
  const rel = HERO_RELICS.find(x => x.id === relicId);
  if(!rel) return;
  const curLv = s.relics.equipped[relicId] || 0;
  const costMetal = rel.costMetal * (curLv + 1);
  const costGems = rel.costGems * (curLv + 1);
  if((s.metal || 0) < costMetal || (s.gems || 0) < costGems){
    G.toast(`❌ Недостаточно ресурсов (нужно ⚙${costMetal}, 💎${costGems})`);
    return;
  }
  s.metal -= costMetal;
  s.gems -= costGems;
  s.relics.equipped[relicId] = curLv + 1;
  s.power = (s.power || 30) + 120;
  if(G.save) G.save();
  G.toast(`✨ Реликвия «${rel.name}» усилена до Ур. ${curLv + 1}! (+120 Мощи)`);
  if(G.rPanel) G.rPanel();
};
