function initClanHelpsShopTechState(){
  if(!G.S) return;
  const s = G.S;
  if(!s.clanHelps){
    s.clanHelps = {
      activeRequests: [...MOCK_CLAN_HELPS],
      myHelpRequested: false,
      totalHelpsGiven: 0
    };
  }
  if(!s.clanShop){
    s.clanShop = {
      honorPoints: 750, // Стартовые очки чести
      purchasedItems: {}
    };
  }
  if(!s.clanTechs){
    s.clanTechs = {
      techs: [...CLAN_TECHS],
      myDonationsToday: 0
    };
  }
}
G.openClanHelpsUI = function(){
  initClanHelpsShopTechState();
  if(G.S) G.S.sub = 'clanhelps';
  if(G.rPanel) G.rPanel();
};
G.helpAllClanMembers = function(){
  initClanHelpsShopTechState();
  const s = G.S;
  if(!s || !s.clanHelps || !s.clanShop) return;
  const unhelped = s.clanHelps.activeRequests.filter(x => !x.helped);
  if(unhelped.length === 0){
    G.toast('❌ Нет активных запросов помощи от соклановцев');
    return;
  }
  unhelped.forEach(x => { x.helped = true; });
  const gainedHonor = unhelped.length * 50;
  s.clanShop.honorPoints = (s.clanShop.honorPoints || 0) + gainedHonor;
  s.clanHelps.totalHelpsGiven = (s.clanHelps.totalHelpsGiven || 0) + unhelped.length;
  if(G.save) G.save();
  G.toast(`🤝 Помощь оказана ${unhelped.length} соклановцам! Получено +${gainedHonor} Очков Чести Клана 🎖`);
  if(G.rPanel) G.rPanel();
};
G.requestClanHelp = function(){
  initClanHelpsShopTechState();
  const s = G.S;
  if(!s || !s.clanHelps) return;
  if(s.clanHelps.myHelpRequested){
    G.toast('⏳ Запрос помощи уже отправлен соклановцам!');
    return;
  }
  s.clanHelps.myHelpRequested = true;
  if(G.save) G.save();
  G.toast('📢 Запрос о помощи отправлен в чат Клана! Союзники ускорят процессы.');
  if(G.rPanel) G.rPanel();
};
