function initVaccinesArtilleryWeatherState(){
  if(!G.S) return;
  const s = G.S;
  if(!s.vaccinesLab){
    s.vaccinesLab = {
      craftedVaccines: {},
      activeBuffs: {}
    };
  }
  if(!s.artillery){
    s.artillery = {
      guns: {
        'art_mortar': { lv: 1, active: true },
        'art_grad': { lv: 0, active: false },
        'art_vulcan': { lv: 0, active: false }
      }
    };
  }
  if(!s.weather){
    s.weather = {
      currentAnomaly: 'weath_dust_storm',
      expiresAt: Date.now() + 3600 * 1000,
      protocolActive: false
    };
  }
}
G.openVaccinesUI = function(){
  initVaccinesArtilleryWeatherState();
  if(G.S) G.S.sub = 'vaccines';
  if(G.rPanel) G.rPanel();
};
G.synthesizeVaccine = function(vacId){
  initVaccinesArtilleryWeatherState();
  const s = G.S;
  if(!s || !s.vaccinesLab) return;
  const vac = ANTIVIRUS_VACCINES.find(x => x.id === vacId);
  if(!vac) return;
  if((s.food || 0) < vac.costFood || (s.gems || 0) < vac.costGems){
    G.toast(`❌ Недостаточно ресурсов (нужно 🍖${vac.costFood}, 💎${vac.costGems})`);
    return;
  }
  s.food -= vac.costFood;
  s.gems -= vac.costGems;
  s.vaccinesLab.craftedVaccines[vacId] = (s.vaccinesLab.craftedVaccines[vacId] || 0) + 1;
  if(vacId === 'vac_immuno_z' && s.woundedMelee !== undefined){
    const healed = Math.min(15, s.woundedMelee);
    s.woundedMelee -= healed;
    if(s.troops) s.troops.melee = (s.troops.melee || 0) + healed;
  }
  s.power = (s.power || 30) + 75;
  if(G.save) G.save();
  G.toast(`🧪 Препарат «${vac.name}» успешно синтезирован! (+75 Мощи)`);
  if(G.rPanel) G.rPanel();
};
