G.upgradeArtilleryGun = function(gunId){
  initVaccinesArtilleryWeatherState();
  const s = G.S;
  if(!s || !s.artillery || !s.artillery.guns) return;
  const gun = SIEGE_ARTILLERY.find(x => x.id === gunId);
  if(!gun) return;
  const cur = s.artillery.guns[gunId] || { lv: 0, active: false };
  const costMetal = gun.costMetal * (cur.lv + 1);
  const costWood = gun.costWood * (cur.lv + 1);
  if((s.metal || 0) < costMetal || (s.wood || 0) < costWood){
    G.toast(`❌ Недостаточно ресурсов (нужно ⚙${costMetal}, 🪵${costWood})`);
    return;
  }
  s.metal -= costMetal;
  s.wood -= costWood;
  cur.lv += 1;
  cur.active = true;
  s.artillery.guns[gunId] = cur;
  s.power = (s.power || 30) + 120;
  if(G.save) G.save();
  G.toast(`💣 Орудие «${gun.name}» модернизировано до Ур. ${cur.lv}! (+120 Мощи)`);
  if(G.rPanel) G.rPanel();
};
