    const count = Math.max(10, Math.round(amount || 25));
    const foodCost = count * 4;
    const metalCost = count * 2;
    if ((s.res?.food || 0) < foodCost || (s.res?.metal || 0) < metalCost) {
      if (typeof G.toast === "function") G.toast(`Не хватает ресурсов на тренировку! Нужно ${foodCost}🍖 ${metalCost}⚙`);
      if (typeof G.snd === "function") G.snd("err");
      return;
    }
    s.res.food -= foodCost;
    s.res.metal -= metalCost;
    if (!s.army) s.army = { melee: 100, ranged: 50, cavalry: 30 };
    s.army[troopType] = (s.army[troopType] || 0) + count;
    s.power = (s.power || 2000) + count * 5;
    const troopNames = { melee: "Рукопашников", ranged: "Стрелков", cavalry: "Мотострелков" };
    if (typeof G.toast === "function") {
      G.toast(`⚔️ Натренировано: +${count} ${troopNames[troopType] || 'бойцов'}! ⚡ +${count*5} Мощи!`);
    }
