/* Script #67 (id=) */
window.TWD_Defense = {
  running: false,
  speed: 1,
  canvas: null,
  ctx: null,
  rafId: null,
  lastTime: 0,
  wave: 1,
  isBoss: false,
  wallHp: 1000,
  wallMaxHp: 1000,
  enemiesRemaining: 0,
  totalEnemies: 0,
  spawnTimer: 0,
  spawnInterval: 1.2,
  defenders: [],
  zombies: [],
  projectiles: [],
  particles: [],
  damageNumbers: [],
  fireZones: [],
  skills: {
    molotov: { cd: 8, maxCd: 8, timer: 0, name: 'Молотов' },
    sniper: { cd: 12, maxCd: 12, timer: 0, name: 'Снайпер' },
    shock: { cd: 15, maxCd: 15, timer: 0, name: 'Ток-сеть' },
    rally: { cd: 20, maxCd: 20, timer: 0, name: 'Клич ража', activeTimer: 0 }
  },
  init() {
    this.canvas = document.getElementById('tdCanvas');
    if (this.canvas) {
      this.ctx = this.canvas.getContext('2d');
      this.resizeCanvas();
      window.addEventListener('resize', () => this.resizeCanvas());
    }
  },
  resizeCanvas() {
    if (!this.canvas) return;
    const container = document.getElementById('tdCanvasContainer');
    if (container) {
      this.canvas.width = container.clientWidth || window.innerWidth;
      this.canvas.height = container.clientHeight || 400;
    }
  },
  startDefense(waveNum = 1, isBoss = false) {
    this.wave = waveNum || (window.G?.S?.wave || 1);
    this.isBoss = !!isBoss;
    this.running = true;
    this.speed = 1;
    this.lastTime = performance.now();
    const overlay = document.getElementById('twdDefenseOverlay');
    if (overlay) overlay.classList.remove('hidden');
    this.resizeCanvas();
    const wallLvl = window.G?.S?.bld?.wall || 1;
    const baseWallHp = window.G?.S?.wHP || (500 + wallLvl * 250);
    const baseWallMax = window.G?.S?.wMax || (500 + wallLvl * 250);
    this.wallHp = baseWallHp;
    this.wallMaxHp = baseWallMax;
    const hordeScale = Math.min(2.5, 1 + this.wave * 0.08);
    this.totalEnemies = Math.floor((12 + this.wave * 3) * hordeScale);
    if (this.isBoss) this.totalEnemies = Math.floor(this.totalEnemies * 0.7) + 1;
    this.enemiesRemaining = this.totalEnemies;
    this.spawnTimer = 0;
    this.spawnInterval = Math.max(0.4, 1.4 - this.wave * 0.02);
    this.setupDefenders();
    this.zombies = [];
    this.projectiles = [];
    this.particles = [];
    this.damageNumbers = [];
    this.fireZones = [];
    for (let k in this.skills) {
      this.skills[k].timer = 0;
      if (this.skills[k].activeTimer !== undefined) this.skills[k].activeTimer = 0;
    }
    this.updateHUD();
    document.getElementById('tdResultModal').style.display = 'none';
    if (window.G && window.G.snd) window.G.snd('waveAlarm');
    if (this.rafId) cancelAnimationFrame(this.rafId);
    this.loop(performance.now());
  },
  setupDefenders() {
    this.defenders = [];
    const gar = window.G?.S?.gar || [];
    const allHeroes = window.G?.S?.heroes || [];
    const garHeroes = gar.map(id => allHeroes.find(h => h.id === id)).filter(Boolean);
    if (garHeroes.length === 0) {
      garHeroes.push({ id: 'def_lead', n: 'Командир', i: '🎖️', a: 15, d: 10, lv: 1, r: 'rare' });
      garHeroes.push({ id: 'def_scout', n: 'Стрелок', i: '🏹', a: 12, d: 8, lv: 1, r: 'common' });
      garHeroes.push({ id: 'def_tech', n: 'Техник', i: '🔧', a: 10, d: 12, lv: 1, r: 'uncommon' });
    }
    const cHeight = this.canvas ? this.canvas.height : 400;
    const slotCount = Math.min(5, garHeroes.length);
    const spacing = cHeight / (slotCount + 1);
    garHeroes.slice(0, 5).forEach((h, idx) => {
      const atk = Math.round((h.a || 10) * (h.lv || 1) * 1.5 + (window.G?.S?.power || 100) * 0.05);
      this.defenders.push({
        hero: h,
        x: 65,
        y: spacing * (idx + 1),
        atk: atk,
        range: 800,
        fireRate: 0.75 + Math.random() * 0.2, // attacks per second
        fireCooldown: 0,
        target: null,
        muzzleFlash: 0
      });
    });
    const bar = document.getElementById('tdHeroesBar');
    if (bar) {
      bar.innerHTML = this.defenders.map(d => `
        <div class="td-hero-slot">
          <div class="td-hero-ico">${d.hero.i || '👤'}</div>
          <div class="td-hero-meta">
            <span class="td-hero-name">${d.hero.n}</span>
            <span class="td-hero-dps">⚔️ ${d.atk} урона</span>
          </div>
        </div>
      `).join('');
    }
  },
  spawnZombie() {
    if (this.enemiesRemaining <= 0) return;
    const cWidth = this.canvas.width;
    const cHeight = this.canvas.height;
    const isBossSpawn = this.isBoss && this.enemiesRemaining === 1;
    let type = 'walker';
    let hp = 120 + this.wave * 45;
    let speed = 28 + Math.random() * 15;
    let size = 16;
    let color = '#22c55e';
    let icon = '🧟';
    let name = 'Ходячий';
    const roll = Math.random();
    if (isBossSpawn) {
      type = 'boss';
      hp = (1200 + this.wave * 450);
      speed = 18;
      size = 32;
      color = '#ef4444';
      icon = '🦏';
      name = 'ТИАТАН-ГОЛИАФ';
    } else if (roll < 0.25) {
      type = 'runner';
      hp = Math.round(hp * 0.65);
      speed = 60 + Math.random() * 20;
      size = 14;
      color = '#f59e0b';
      icon = '⚡';
      name = 'Бегун';
    } else if (roll < 0.45) {
      type = 'spitter';
      hp = Math.round(hp * 0.85);
      speed = 22;
      size = 17;
      color = '#a855f7';
      icon = '🧪';
      name = 'Спиттер';
    }
    const laneY = 50 + Math.random() * (cHeight - 100);
    this.zombies.push({
      type,
      name,
      icon,
      x: cWidth + 20,
      y: laneY,
      hp,
      maxHp: hp,
      speed,
      size,
      color,
      attackDmg: type === 'boss' ? 45 : (type === 'runner' ? 12 : 18),
      attackRate: 1.0,
      attackCooldown: 0,
      stunTimer: 0,
      burnTimer: 0
    });
    this.enemiesRemaining--;
  },
  loop(now) {
    if (!this.running) return;
    const dt = Math.min((now - this.lastTime) / 1000, 0.1) * this.speed;
    this.lastTime = now;
    this.update(dt);
    this.render();
    this.rafId = requestAnimationFrame(t => this.loop(t));
  },
  update(dt) {
    if (this.enemiesRemaining > 0) {
      this.spawnTimer += dt;
      if (this.spawnTimer >= this.spawnInterval) {
        this.spawnTimer = 0;
        this.spawnZombie();
      }
    }
    for (let k in this.skills) {
      const sk = this.skills[k];
      if (sk.timer > 0) {
        sk.timer = Math.max(0, sk.timer - dt);
      }
      if (sk.activeTimer && sk.activeTimer > 0) {
        sk.activeTimer = Math.max(0, sk.activeTimer - dt);
      }
      const cdOverlay = document.getElementById('tdSkillCd_' + k);
      const btn = document.getElementById('tdSkill_' + k);
      if (cdOverlay && btn) {
        if (sk.timer > 0) {
          cdOverlay.style.display = 'flex';
          cdOverlay.textContent = Math.ceil(sk.timer) + 's';
          btn.classList.remove('ready');
          btn.classList.add('on-cd');
        } else {
          cdOverlay.style.display = 'none';
          btn.classList.add('ready');
          btn.classList.remove('on-cd');
        }
      }
    }
    for (let i = this.fireZones.length - 1; i >= 0; i--) {
      const fz = this.fireZones[i];
      fz.duration -= dt;
      fz.tickTimer = (fz.tickTimer || 0) + dt;
      if (fz.tickTimer >= 0.4) {
        fz.tickTimer = 0;
        this.zombies.forEach(z => {
          const dist = Math.hypot(z.x - fz.x, z.y - fz.y);
          if (dist <= fz.radius) {
            z.hp -= fz.dps * 0.4;
            z.burnTimer = 2.0;
            this.addDamageNumber(z.x, z.y - 10, Math.round(fz.dps * 0.4), '#f97316');
          }
        });
      }
      if (fz.duration <= 0) this.fireZones.splice(i, 1);
    }
    const isRallyActive = this.skills.rally.activeTimer > 0;
    this.defenders.forEach(d => {
      d.fireCooldown -= dt * (isRallyActive ? 2.0 : 1.0);
      if (d.muzzleFlash > 0) d.muzzleFlash -= dt * 5;
      let bestTarget = null;
      let minX = 99999;
      this.zombies.forEach(z => {
        if (z.hp > 0 && z.x < minX) {
          minX = z.x;
          bestTarget = z;
        }
      });
      d.target = bestTarget;
      if (d.fireCooldown <= 0 && d.target) {
        d.fireCooldown = 1.0 / d.fireRate;
        d.muzzleFlash = 1.0;
        const isCrit = Math.random() < (isRallyActive ? 0.4 : 0.15);
        const dmg = Math.round(d.atk * (isCrit ? 2.0 : 1.0));
        this.projectiles.push({
          x: d.x + 20,
          y: d.y,
          target: d.target,
          speed: 700,
          dmg: dmg,
          isCrit: isCrit,
          color: isCrit ? '#f59e0b' : '#38bdf8'
        });
        if (window.G?.snd && Math.random() < 0.25) window.G.snd('click');
      }
    });
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      if (!p.target || p.target.hp <= 0) {
        p.x += p.speed * dt;
        if (p.x > this.canvas.width + 50) this.projectiles.splice(i, 1);
        continue;
      }
      const dx = p.target.x - p.x;
      const dy = p.target.y - p.y;
      const dist = Math.hypot(dx, dy);
      if (dist < 15) {
        p.target.hp -= p.dmg;
        this.addDamageNumber(p.target.x, p.target.y - 15, p.dmg, p.isCrit ? '#fbbf24' : '#ffffff', p.isCrit);
        this.addHitParticles(p.target.x, p.target.y, p.color);
        this.projectiles.splice(i, 1);
      } else {
        p.x += (dx / dist) * p.speed * dt;
        p.y += (dy / dist) * p.speed * dt;
      }
    }
    const wallX = 90;
    for (let i = this.zombies.length - 1; i >= 0; i--) {
      const z = this.zombies[i];
      if (z.stunTimer > 0) {
        z.stunTimer -= dt;
        continue;
      }
      if (z.burnTimer > 0) {
        z.burnTimer -= dt;
        z.hp -= 25 * dt;
      }
      if (z.hp <= 0) {
        this.addDeathParticles(z.x, z.y, z.color);
        this.zombies.splice(i, 1);
        continue;
      }
      if (z.x > wallX + 15) {
        const moveSpeed = z.burnTimer > 0 ? z.speed * 0.6 : z.speed;
        z.x -= moveSpeed * dt;
      } else {
        z.attackCooldown -= dt;
        if (z.attackCooldown <= 0) {
          z.attackCooldown = 1.0 / z.attackRate;
          this.wallHp = Math.max(0, this.wallHp - z.attackDmg);
          this.addDamageNumber(wallX, z.y, z.attackDmg, '#ef4444', false);
          this.addHitParticles(wallX, z.y, '#ef4444');
          if (window.G?.snd) window.G.snd('wallHit');
          if (this.wallHp <= 0) {
            this.handleDefeat();
            return;
          }
        }
      }
    }
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const pt = this.particles[i];
      pt.x += pt.vx * dt;
      pt.y += pt.vy * dt;
      pt.life -= dt;
      if (pt.life <= 0) this.particles.splice(i, 1);
    }
    for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
      const dn = this.damageNumbers[i];
      dn.y -= 25 * dt;
      dn.life -= dt;
      if (dn.life <= 0) this.damageNumbers.splice(i, 1);
    }
    if (this.enemiesRemaining <= 0 && this.zombies.length === 0 && this.wallHp > 0) {
      this.handleVictory();
    }
    this.updateHUD();
  },
  render() {
    if (!this.ctx || !this.canvas) return;
    const ctx = this.ctx;
    const w = this.canvas.width;
    const h = this.canvas.height;
    ctx.clearRect(0, 0, w, h);
    const wallX = 90;
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(0, 0, wallX, h);
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(wallX, 0);
    ctx.lineTo(wallX, h);
    ctx.stroke();
    ctx.fillStyle = '#94a3b8';
    for (let y = 15; y < h; y += 30) {
      ctx.beginPath();
      ctx.moveTo(wallX, y);
      ctx.lineTo(wallX + 12, y + 6);
      ctx.lineTo(wallX, y + 12);
      ctx.fill();
    }
    ctx.strokeStyle = 'rgba(56, 189, 248, 0.25)';
    ctx.lineWidth = 6;
    ctx.strokeRect(wallX - 4, 0, 8, h);
    this.fireZones.forEach(fz => {
      ctx.save();
      const grad = ctx.createRadialGradient(fz.x, fz.y, 5, fz.x, fz.y, fz.radius);
      grad.addColorStop(0, 'rgba(239, 68, 68, 0.7)');
      grad.addColorStop(0.5, 'rgba(245, 158, 11, 0.45)');
      grad.addColorStop(1, 'rgba(245, 158, 11, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(fz.x, fz.y, fz.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    });
    this.defenders.forEach(d => {
      ctx.fillStyle = '#0f172a';
      ctx.beginPath();
      ctx.arc(d.x, d.y, 18, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#f59e0b';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(d.hero.i || '🏹', d.x, d.y);
      if (d.muzzleFlash > 0) {
        ctx.fillStyle = 'rgba(253, 224, 71, ' + d.muzzleFlash + ')';
        ctx.beginPath();
        ctx.arc(d.x + 22, d.y, 10 * d.muzzleFlash, 0, Math.PI * 2);
        ctx.fill();
      }
      if (this.skills.rally.activeTimer > 0) {
        ctx.strokeStyle = 'rgba(245, 158, 11, 0.8)';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(d.x, d.y, 22 + Math.sin(performance.now() * 0.01) * 3, 0, Math.PI * 2);
        ctx.stroke();
      }
    });
    this.projectiles.forEach(p => {
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.isCrit ? 5 : 3.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = p.color;
      ctx.lineWidth = p.isCrit ? 3 : 1.5;
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
      ctx.lineTo(p.x - 12, p.y);
      ctx.stroke();
    });
    this.zombies.forEach(z => {
      ctx.save();
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.beginPath();
      ctx.ellipse(z.x, z.y + z.size * 0.8, z.size * 0.8, z.size * 0.4, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = z.color;
      ctx.beginPath();
      ctx.arc(z.x, z.y, z.size, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ctx.font = (z.size * 1.3) + 'px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(z.icon, z.x, z.y);
      if (z.stunTimer > 0) {
        ctx.font = '12px sans-serif';
        ctx.fillText('⚡', z.x, z.y - z.size - 10);
      }
      const hpPct = Math.max(0, z.hp / z.maxHp);
      const barW = z.size * 2.2;
      const barH = 4;
      const barX = z.x - barW / 2;
      const barY = z.y - z.size - 6;
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(barX, barY, barW, barH);
      ctx.fillStyle = z.type === 'boss' ? '#ef4444' : '#22c55e';
      ctx.fillRect(barX, barY, barW * hpPct, barH);
      ctx.restore();
    });
    this.particles.forEach(pt => {
      ctx.fillStyle = pt.color;
      ctx.globalAlpha = Math.max(0, pt.life / pt.maxLife);
      ctx.beginPath();
      ctx.arc(pt.x, pt.y, pt.size, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1.0;
    });
    this.damageNumbers.forEach(dn => {
      ctx.save();
      ctx.fillStyle = dn.color;
      ctx.font = dn.isCrit ? 'bold 15px sans-serif' : 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.globalAlpha = Math.max(0, dn.life / dn.maxLife);
      ctx.fillText(dn.text, dn.x, dn.y);
      ctx.restore();
    });
  },
  addDamageNumber(x, y, amount, color = '#ffffff', isCrit = false) {
    this.damageNumbers.push({
      x,
      y,
      text: (isCrit ? '💥 ' : '') + '-' + amount,
      color,
      isCrit,
      life: 0.8,
      maxLife: 0.8
    });
  },
  addHitParticles(x, y, color) {
    for (let i = 0; i < 4; i++) {
      this.particles.push({
        x,
        y,
        vx: (Math.random() - 0.5) * 80,
        vy: (Math.random() - 0.5) * 80,
        size: 2 + Math.random() * 2,
        color: color,
        life: 0.3,
        maxLife: 0.3
      });
    }
  },
  addDeathParticles(x, y, color) {
    for (let i = 0; i < 8; i++) {
      this.particles.push({
        x,
        y,
        vx: (Math.random() - 0.5) * 120,
        vy: (Math.random() - 0.5) * 120,
        size: 3 + Math.random() * 3,
        color: color,
        life: 0.5,
        maxLife: 0.5
      });
    }
  },
  activateSkill(skillKey) {
    const sk = this.skills[skillKey];
    if (!sk || sk.timer > 0 || !this.running) return;
    sk.timer = sk.maxCd;
    if (skillKey === 'molotov') {
      const fzX = (this.canvas.width + 120) / 2;
      const fzY = this.canvas.height / 2;
      this.fireZones.push({
        x: fzX,
        y: fzY,
        radius: 90,
        duration: 5.0,
        dps: 180 + this.wave * 30
      });
      if (window.G?.snd) window.G.snd('reward');
      if (window.G?.toast) window.G.toast('🔥 Коктейль Молотова: Стена пламени!');
    } else if (skillKey === 'sniper') {
      let highestHpTarget = null;
      let maxHp = -1;
      this.zombies.forEach(z => {
        if (z.hp > maxHp) {
          maxHp = z.hp;
          highestHpTarget = z;
        }
      });
      if (highestHpTarget) {
        const sniperDmg = Math.round(550 + this.wave * 120 + (window.G?.S?.power || 100) * 0.8);
        highestHpTarget.hp -= sniperDmg;
        this.addDamageNumber(highestHpTarget.x, highestHpTarget.y - 20, sniperDmg, '#38bdf8', true);
        this.addHitParticles(highestHpTarget.x, highestHpTarget.y, '#38bdf8');
        this.particles.push({
          x: highestHpTarget.x,
          y: highestHpTarget.y,
          vx: 0,
          vy: 0,
          size: 18,
          color: '#38bdf8',
          life: 0.4,
          maxLife: 0.4
        });
      }
      if (window.G?.snd) window.G.snd('click');
      if (window.G?.toast) window.G.toast('🎯 Снайперский залп: Точный выстрел!');
    } else if (skillKey === 'shock') {
      this.zombies.forEach(z => {
        if (z.x < 350) {
          z.stunTimer = 3.5;
          z.hp -= 100;
          this.addDamageNumber(z.x, z.y - 10, 100, '#a855f7');
          this.addHitParticles(z.x, z.y, '#a855f7');
        }
      });
      if (window.G?.snd) window.G.snd('build');
      if (window.G?.toast) window.G.toast('⚡ Электро-сетка: Волна оглушена!');
    } else if (skillKey === 'rally') {
      sk.activeTimer = 5.0;
      if (window.G?.snd) window.G.snd('reward');
      if (window.G?.toast) window.G.toast('📢 Боевой клич: Скорость атаки ×2!');
    }
  },
  handleCanvasClick(e) {
    if (!this.running || !this.canvas) return;
    const rect = this.canvas.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const clickY = e.clientY - rect.top;
    const tapDmg = 40 + this.wave * 10;
    let hitZombie = null;
    this.zombies.forEach(z => {
      const dist = Math.hypot(z.x - clickX, z.y - clickY);
      if (dist <= z.size + 15) {
        hitZombie = z;
      }
    });
    if (hitZombie) {
      hitZombie.hp -= tapDmg;
      this.addDamageNumber(hitZombie.x, hitZombie.y - 10, tapDmg, '#f59e0b');
      this.addHitParticles(hitZombie.x, hitZombie.y, '#f59e0b');
    }
  },
  toggleSpeed() {
    this.speed = this.speed === 1 ? 2 : 1;
    const btn = document.getElementById('tdSpeedBtn');
    if (btn) btn.textContent = this.speed + 'X';
  },
  updateHUD() {
    const wallHpText = document.getElementById('tdWallHpText');
    const wallHpFill = document.getElementById('tdWallHpFill');
    if (wallHpText && wallHpFill) {
      const pct = Math.max(0, Math.min(100, (this.wallHp / this.wallMaxHp) * 100));
      wallHpText.textContent = Math.round(this.wallHp) + ' / ' + this.wallMaxHp;
      wallHpFill.style.width = pct + '%';
      wallHpFill.style.background = pct > 50 ? 'linear-gradient(90deg, #22c55e, #16a34a)' : (pct > 25 ? 'linear-gradient(90deg, #f59e0b, #d97706)' : 'linear-gradient(90deg, #ef4444, #b91c1c)');
    }
    const waveTitle = document.getElementById('tdWaveTitle');
    const enemyCount = document.getElementById('tdEnemyCount');
    if (waveTitle && enemyCount) {
      waveTitle.textContent = this.isBoss ? '👑 БОЙ С ТИТАН-БОССОМ' : ('⚔️ ВОЛНА ОРДЫ ' + this.wave);
      const totalActive = this.enemiesRemaining + this.zombies.length;
      enemyCount.textContent = 'Осталось: ' + totalActive + ' / ' + this.totalEnemies;
    }
  },
  handleVictory() {
    this.running = false;
    if (this.rafId) cancelAnimationFrame(this.rafId);
    if (window.G && window.G.S) {
      window.G.S.wave = (window.G.S.wave || 1) + 1;
      window.G.S.kills = (window.G.S.kills || 0) + this.totalEnemies;
      window.G.S.wHP = Math.round(this.wallHp);
      const foodReward = Math.round(150 + this.wave * 45);
      const woodReward = Math.round(100 + this.wave * 35);
      const metalReward = Math.round(80 + this.wave * 25);
      const gemsReward = this.isBoss ? 50 : 15;
      window.G.S.res.food = Math.min((window.G.S.res.food || 0) + foodReward, window.G.S.caps?.food || 99999);
      window.G.S.res.wood = Math.min((window.G.S.res.wood || 0) + woodReward, window.G.S.caps?.wood || 99999);
      window.G.S.res.metal = Math.min((window.G.S.res.metal || 0) + metalReward, window.G.S.caps?.metal || 99999);
      window.G.S.res.gems = Math.min((window.G.S.res.gems || 0) + gemsReward, window.G.S.caps?.gems || 99999);
      if (window.G.addXP) window.G.addXP(40 + this.wave * 10);
      if (window.G.heroXp) window.G.heroXp(25 + this.wave * 5);
      if (window.G.bondXp) window.G.bondXp(2);
      const modal = document.getElementById('tdResultModal');
      const title = document.getElementById('tdResultTitle');
      const sub = document.getElementById('tdResultSub');
      const rewardsGrid = document.getElementById('tdRewardsGrid');
      const btn = document.getElementById('tdResultBtn');
      if (modal && title && rewardsGrid) {
        title.className = 'td-result-title win';
        title.textContent = '🏆 ВОЛНА ' + (this.wave) + ' ОТБИТА!';
        sub.textContent = 'Орда отброшена от укреплений! База в безопасности.';
        rewardsGrid.innerHTML = `
          <div class="td-reward-item"><span>🌾</span>+${foodReward}</div>
          <div class="td-reward-item"><span>🪵</span>+${woodReward}</div>
          <div class="td-reward-item"><span>🔩</span>+${metalReward}</div>
          <div class="td-reward-item"><span>💎</span>+${gemsReward}</div>
          <div class="td-reward-item"><span>💀</span>+${this.totalEnemies}</div>
          <div class="td-reward-item"><span>⭐</span>+${40 + this.wave * 10} XP</div>
        `;
        btn.textContent = 'ЗАБРАТЬ ТРОФЕИ И ВЕРНУТЬСЯ В ГОРОД';
        modal.style.display = 'flex';
      }
      if (window.G.snd) window.G.snd('victory');
      if (window.G.updAll) window.G.updAll();
    }
  },
  handleDefeat() {
    this.running = false;
    if (this.rafId) cancelAnimationFrame(this.rafId);
    if (window.G && window.G.S) {
      window.G.S.wHP = 0;
      if (window.G.updAll) window.G.updAll();
    }
    const modal = document.getElementById('tdResultModal');
    const title = document.getElementById('tdResultTitle');
    const sub = document.getElementById('tdResultSub');
    const rewardsGrid = document.getElementById('tdRewardsGrid');
    const btn = document.getElementById('tdResultBtn');
    if (modal && title && rewardsGrid) {
      title.className = 'td-result-title lose';
      title.textContent = '💀 ВОРОТА ПРОБИТЫ!';
      sub.textContent = 'Орда прорвала периметр. Требуется срочный ремонт частокола!';
      rewardsGrid.innerHTML = `
        <div class="td-reward-item"><span>🧱</span>Стена пала</div>
        <div class="td-reward-item"><span>🔧</span>Нужен ремонт</div>
        <div class="td-reward-item"><span>💀</span>+${this.totalEnemies - this.enemiesRemaining - this.zombies.length}</div>
      `;
      btn.textContent = 'ОТСТУПИТЬ И ВОССТАНОВИТЬ ОБОРОНУ';
      modal.style.display = 'flex';
    }
    if (window.G?.snd) window.G.snd('wallHit');
  },
  retreat() {
    this.running = false;
    if (this.rafId) cancelAnimationFrame(this.rafId);
    const overlay = document.getElementById('twdDefenseOverlay');
    if (overlay) overlay.classList.add('hidden');
    if (window.G && window.G.updAll) window.G.updAll();
  },
  closeResultModal() {
    const modal = document.getElementById('tdResultModal');
    if (modal) modal.style.display = 'none';
    this.retreat();
  }
};
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => window.TWD_Defense.init());
} else {
  window.TWD_Defense.init();
};
/* Script #68 (id=) */
window.TWD_Army = {
  activeTab: 'melee', // melee | ranged | cavalry | hospital
  tiers: {
    melee: [
      { id: 't1', tier: 1, reqBar: 1, name: 'Ополченцы-Ножевики', icon: '🗡️', atk: 14, def: 20, hp: 130, cost: { food: 20, wood: 10 } },
      { id: 't2', tier: 2, reqBar: 4, name: 'Мачетеносцы Заставы', icon: '🪓', atk: 28, def: 40, hp: 260, cost: { food: 45, wood: 25, metal: 10 } },
      { id: 't3', tier: 3, reqBar: 7, name: 'Щитоносцы «Апекс»', icon: '🛡️', atk: 52, def: 75, hp: 500, cost: { food: 90, wood: 50, metal: 30 } },
      { id: 't4', tier: 4, reqBar: 10, name: 'Джаггернауты Цитадели', icon: '⚔️', atk: 95, def: 135, hp: 920, cost: { food: 180, wood: 100, metal: 70 } }
    ],
    ranged: [
      { id: 't1', tier: 1, reqBar: 1, name: 'Стрелки с Луками', icon: '🏹', atk: 20, def: 8, hp: 90, cost: { food: 20, wood: 15 } },
      { id: 't2', tier: 2, reqBar: 4, name: 'Карабинеры Патруля', icon: '🔫', atk: 42, def: 18, hp: 180, cost: { food: 45, wood: 30, metal: 15 } },
      { id: 't3', tier: 3, reqBar: 7, name: 'Снайперы-Ликвидаторы', icon: '🎯', atk: 78, def: 35, hp: 340, cost: { food: 95, wood: 60, metal: 35 } },
      { id: 't4', tier: 4, reqBar: 10, name: 'Пулеметчики «Апекс»', icon: '💥', atk: 140, def: 60, hp: 620, cost: { food: 190, wood: 110, metal: 80 } }
    ],
    cavalry: [
      { id: 't1', tier: 1, reqBar: 1, name: 'Разведчики на Байках', icon: '🏍️', atk: 16, def: 14, hp: 110, cost: { food: 25, metal: 15 } },
      { id: 't2', tier: 2, reqBar: 4, name: 'Рейдеры Пустошей', icon: '🏎️', atk: 34, def: 28, hp: 220, cost: { food: 55, wood: 20, metal: 25 } },
      { id: 't3', tier: 3, reqBar: 7, name: 'Штурмовые Мотоциклисты', icon: '🚜', atk: 65, def: 52, hp: 410, cost: { food: 110, wood: 40, metal: 50 } },
      { id: 't4', tier: 4, reqBar: 10, name: 'Броне-Кавалеристы', icon: '🦾', atk: 115, def: 90, hp: 760, cost: { food: 210, wood: 80, metal: 95 } }
    ]
  },
  initArmyState() {
    if (!window.G || !window.G.S) return;
    if (!window.G.S.army) {
      window.G.S.army = {
        melee: { t1: 20, t2: 0, t3: 0, t4: 0 },
        ranged: { t1: 15, t2: 0, t3: 0, t4: 0 },
        cavalry: { t1: 10, t2: 0, t3: 0, t4: 0 }
      };
    }
    if (!window.G.S.hospital) {
      window.G.S.hospital = {
        wounded: { melee: 0, ranged: 0, cavalry: 0 }
      };
    }
  },
  openModal(tab = 'melee') {
    this.initArmyState();
    this.activeTab = tab;
    const modal = document.getElementById('twdArmyModal');
    if (modal) {
      modal.classList.remove('hidden');
      this.render();
    }
  },
  closeModal() {
    const modal = document.getElementById('twdArmyModal');
    if (modal) modal.classList.add('hidden');
    if (window.G && window.G.updAll) window.G.updAll();
  },
  switchTab(tab) {
    this.activeTab = tab;
    ['melee', 'ranged', 'cav', 'hosp'].forEach(t => {
      const btn = document.getElementById('twdArmyTab_' + t);
      if (btn) btn.classList.toggle('active', (t === 'cav' && tab === 'cavalry') || (t === 'hosp' && tab === 'hospital') || t === tab);
    });
    this.render();
  },
  render() {
    this.initArmyState();
    const body = document.getElementById('twdArmyBody');
    if (!body) return;
    if (this.activeTab === 'hospital') {
      this.renderHospital(body);
      return;
    }
    const barLvl = (window.G?.S?.bld?.bar || 1);
    const armyData = window.G?.S?.army[this.activeTab] || { t1: 0, t2: 0, t3: 0, t4: 0 };
    const tierList = this.tiers[this.activeTab] || [];
    const totalInClass = (armyData.t1 || 0) + (armyData.t2 || 0) + (armyData.t3 || 0) + (armyData.t4 || 0);
    let html = `
      <div style="display:flex;justify-content:space-between;align-items:center;background:rgba(0,0,0,0.3);padding:6px 10px;border-radius:8px">
        <span style="font-size:11px;font-weight:900;color:#f1f5f9">Численность в строю: <b style="color:#f59e0b">${totalInClass} бойцов</b></span>
        <span style="font-size:9.5px;color:#94a3b8">Казарма: Ур.${barLvl}</span>
      </div>
    `;
    tierList.forEach(t => {
      const isUnlocked = barLvl >= t.reqBar;
      const count = armyData[t.id] || 0;
      html += `
        <div class="twd-troop-card ${isUnlocked ? '' : 'locked'}">
          <div class="twd-troop-top">
            <div class="twd-troop-name">
              <span>${t.icon}</span>
              <span>${t.name}</span>
            </div>
            <div class="twd-troop-tier-badge ${t.id}">
              ${isUnlocked ? `Тир ${t.tier} · В строю: ${count}` : `🔒 Казарма Ур.${t.reqBar}`}
            </div>
          </div>
          <div class="twd-troop-stats">
            <div>⚔️ Атака: <b>${t.atk}</b></div>
            <div>🛡️ Защита: <b>${t.def}</b></div>
            <div>❤️ Здоровье: <b>${t.hp}</b></div>
          </div>
          ${isUnlocked ? `
            <div class="twd-troop-actions">
              <button class="twd-train-btn" onclick="TWD_Army.trainTroops('${this.activeTab}', '${t.id}', 10)">
                Тренировать +10 (🍖${t.cost.food * 10} 🪵${(t.cost.wood || 0) * 10})
              </button>
              <button class="twd-train-btn" style="background:linear-gradient(135deg,#38bdf8,#0284c7);color:#fff" onclick="TWD_Army.trainTroops('${this.activeTab}', '${t.id}', 50)">
                +50
              </button>
            </div>
          ` : `
            <div style="font-size:9px;color:#f87171;text-align:center;padding:4px">
              Требуется улучшить Казарму до Уровня ${t.reqBar}
            </div>
          `}
        </div>
      `;
    });
    body.innerHTML = html;
  },
  renderHospital(body) {
    const hospLvl = (window.G?.S?.bld?.hosp || 1);
    const capacity = hospLvl * 100;
    const wounded = window.G?.S?.hospital?.wounded || { melee: 0, ranged: 0, cavalry: 0 };
    const totalWounded = (wounded.melee || 0) + (wounded.ranged || 0) + (wounded.cavalry || 0);
    const healFoodCost = totalWounded * 5;
    body.innerHTML = `
      <div class="twd-hospital-summary">
        <div class="twd-hosp-title">
          <span>🏥 ГОСПИТАЛЬ ЦИТАДЕЛИ</span>
          <span>Койки: ${totalWounded} / ${capacity}</span>
        </div>
        <div style="font-size:9.5px;color:#cbd5e1;line-height:1.4">
          После тяжелых волн обороны и вылазок раненые бойцы поступают в палаты. Перевязка мгновенно возвращает их в строй.
        </div>
      </div>
      <div style="display:flex;flex-direction:column;gap:6px">
        <div class="twd-troop-card" style="padding:8px">
          <div style="display:flex;justify-content:space-between;font-size:11px">
            <span>🗡️ Раненые защитники:</span>
            <b>${wounded.melee || 0} бойцов</b>
          </div>
        </div>
        <div class="twd-troop-card" style="padding:8px">
          <div style="display:flex;justify-content:space-between;font-size:11px">
            <span>🏹 Раненые стрелки:</span>
            <b>${wounded.ranged || 0} бойцов</b>
          </div>
        </div>
        <div class="twd-troop-card" style="padding:8px">
          <div style="display:flex;justify-content:space-between;font-size:11px">
            <span>🏍️ Раненые всадники:</span>
            <b>${wounded.cavalry || 0} бойцов</b>
          </div>
        </div>
      </div>
      ${totalWounded > 0 ? `
        <button class="twd-hosp-heal-btn" onclick="TWD_Army.healAll()">
          🩺 ПЕРЕВЯЗАТЬ И ИСЦЕЛИТЬ ВСЕХ (${totalWounded} бойцов · 🍖${healFoodCost})
        </button>
      ` : `
        <div style="text-align:center;padding:16px;font-size:11px;color:#4ade80;background:rgba(0,0,0,0.3);border-radius:8px">
          ✨ Палаты пусты! Все бойцы колонии здоровы и готовы к бою.
        </div>
      `}
    `;
  },
  trainTroops(cls, tierKey, count = 10) {
    this.initArmyState();
    const tDef = this.tiers[cls]?.find(t => t.id === tierKey);
    if (!tDef) return;
    const foodCost = (tDef.cost.food || 0) * count;
    const woodCost = (tDef.cost.wood || 0) * count;
    const metalCost = (tDef.cost.metal || 0) * count;
    const res = window.G?.S?.res || {};
    if ((res.food || 0) < foodCost || (res.wood || 0) < woodCost || (res.metal || 0) < metalCost) {
      if (window.G?.toast) window.G.toast('Не хватает ресурсов для тренировки!');
      return;
    }
    res.food -= foodCost;
    res.wood -= woodCost;
    res.metal -= metalCost;
    window.G.S.army[cls][tierKey] = (window.G.S.army[cls][tierKey] || 0) + count;
    const powerAdd = Math.round((tDef.atk + tDef.def) * count * 0.25);
    window.G.S.power = (window.G.S.power || 100) + powerAdd;
    if (window.G?.snd) window.G.snd('build');
    if (window.G?.toast) window.G.toast(`⚔️ Обучено +${count} ${tDef.name}! Боевая мощь +${powerAdd}`);
    this.render();
    if (window.G?.updAll) window.G.updAll();
  },
  healAll() {
    this.initArmyState();
    const wounded = window.G?.S?.hospital?.wounded || {};
    const totalWounded = (wounded.melee || 0) + (wounded.ranged || 0) + (wounded.cavalry || 0);
    if (totalWounded <= 0) return;
    const foodCost = totalWounded * 5;
    if ((window.G?.S?.res?.food || 0) < foodCost) {
      if (window.G?.toast) window.G.toast('Не хватает провианта для лечения!');
      return;
    }
    window.G.S.res.food -= foodCost;
    window.G.S.army.melee.t1 = (window.G.S.army.melee.t1 || 0) + (wounded.melee || 0);
    window.G.S.army.ranged.t1 = (window.G.S.army.ranged.t1 || 0) + (wounded.ranged || 0);
    window.G.S.army.cavalry.t1 = (window.G.S.army.cavalry.t1 || 0) + (wounded.cavalry || 0);
    wounded.melee = 0;
    wounded.ranged = 0;
    wounded.cavalry = 0;
    if (window.G?.snd) window.G.snd('reward');
    if (window.G?.toast) window.G.toast(`🩺 ${totalWounded} бойцов исцелены и вернулись в строй!`);
    this.render();
    if (window.G?.updAll) window.G.updAll();
  }
};
